import React from "react";
// Redux
import { connect } from "react-redux";
import { fetchSettlementBreakdown } from "../../../../../actions/filesets";
import { fetchAffiliatesNamesAndCodes, getRegionCodes } from "../../../../../actions/affiliates";

// component
import SettlementBreakdownMain from "./SettlementBreakdownMain";

const SettlementBreakdown = ({ ...props }) => {
	return <SettlementBreakdownMain {...props} />;
};

const mapStateToProps = (state) => {
	return {
		selectedAffiliateCode      : state.fileSets.selectedAffiliateCode,
		settlement_breakdown       : state.fileSets.settlement_breakdown,
		settlement_breakdown_error : state.fileSets.settlement_breakdown_error,
		regionCodes                : state.affiliates.region_codes,
		allAffiliates              : state.affiliates.affiliatesNamesAndCodes,
	};
};

export default connect(mapStateToProps, {
	fetchSettlementBreakdown,
	fetchAffiliatesNamesAndCodes,
	getRegionCodes,
})(SettlementBreakdown);
