// Styles
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

// React
import React, { useState, useEffect } from "react";
import { useHistory } from "react-router-dom";
import { FormattedMessage } from "react-intl";
import { SingleDatePicker } from "react-dates";
import Loader from "react-loader-spinner";
import moment from "moment";
import Select from "react-select";

// Components
import { Button, Card, CardBody, CardHeader, Col, Row, Table as Table2 } from "reactstrap";
import PostingTableHeader from "../../../../../components/PostingTableHeader";
import PostingTable from "../../../../../components/PostingTable";
import ErrorMessage from "../../../../../components/ErrorMessage";

const SettlementBreakdownMain = ({
	// function props
	getRegionCodes,
	fetchAffiliatesNamesAndCodes,
	fetchSettlementBreakdown,
	// query string props
	location,
	// state variables props
	regionCodes,
	settlement_breakdown,
	settlement_breakdown_error,
}) => {
	// query string
	const queryString = require("query-string");
	const queryParams = location && location.search && location.search;
	const history = useHistory(); // save react router history to history

	// QUERY STRING VARIABLES
	let { settlementDate } = queryString.parse(queryParams);
	let regionCode = queryString.parse(queryParams)["region-code"];

	const [ focused, setFocused ] = useState(false);
	const [ startDate, setStartDate ] = useState(moment(settlementDate));
	useEffect(
		() => {
			setStartDate(moment(settlementDate));
		},
		[ settlementDate ],
	);

	// React select ony takes objec e.g {label: "USD": value:"USD"} so this construct achieves this but is also dynamic to what ever is passed as the region code in the query string.
	const [ selectedRegion, setSelectedRegion ] = useState({
		label : regionCode,
		value : regionCode,
	});
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setSelectedRegion({
				label : regionCode,
				value : regionCode,
			});
		},
		[ regionCode ],
	);

	// Use Effect Handles General Updates
	useEffect(
		() => {
			getRegionCodes();
			fetchAffiliatesNamesAndCodes();
			fetchSettlementBreakdown(settlementDate, regionCode);
		},
		[ queryParams ],
	);

	const handleSubmitDate = (selectedDate, region) => {
		let settlementDate = moment(selectedDate).format("YYYY-MM-DD");
		history.push(
			`/interaffiliate/reports/settlement-breakdown?settlementDate=${settlementDate}&region-code=${region.label}`,
		);
	};

	const SettlemenBreakdownHeader = [
		"Affiliate",
		"Acquiring Amount",
		"Acquiring Fee",
		"Issuing Amount",
		"Issuing Fee",
		"Net",
	];

	const createRegionList = (regionCodes) => {
		let SelectRegion = [];
		SelectRegion =
			regionCodes &&
			regionCodes.map((region) => {
				return { label: region.code, value: region };
			});
		return SelectRegion;
	};

	return (
		<div className='animated fadeIn'>
			<Row>
				<Col lg={12}>
					<Card>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<React.Fragment>
									{settlementDate}
									<FormattedMessage
										id=' Settlement Breakdown'
										defaultMessage=' Settlement Breakdown'
									/>
								</React.Fragment>
							</strong>

							<div className={"d-flex justify-content-end align-items-center w-50"}>
								<React.Fragment>
									<SingleDatePicker
										showDefaultInputIcon={true}
										date={startDate} // momentPropTypes.momentObj or null
										onDateChange={(startDate) => setStartDate(startDate)} // PropTypes.func.isRequired
										focused={focused} // PropTypes.bool
										onFocusChange={({ focused }) => setFocused(focused)} // PropTypes.func.isRequired
										id='your_unique_id' // PropTypes.string.isRequired,
										isOutsideRange={() => false}
										numberOfMonths={1}
									/>
									<React.Fragment>
										<Select
											className={"w-25 mx-2"}
											onChange={(selectedOption) => setSelectedRegion(selectedOption)}
											value={selectedRegion}
											options={createRegionList(regionCodes && regionCodes)}
										/>
									</React.Fragment>
									<Button
										style={{
											padding                : "9px",
											borderTopLeftRadius    : "0px",
											borderBottomLeftRadius : "0px",
										}}
										className={"btn-sm mx-1"}
										onClick={() => handleSubmitDate(startDate, selectedRegion)}
										color='primary'
									>
										{" "}
										<FormattedMessage id='Submit' defaultMessage='Submit' />
									</Button>
								</React.Fragment>
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!settlement_breakdown_error &&
							!settlement_breakdown && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle unselected fields */}
							{regionCode === "Region" &&
							!settlement_breakdown &&
							settlement_breakdown_error && (
								<ErrorMessage
									message={
										"Please select your region code and date and click Submit to view entries!"
									}
								/>
							)}

							{/* Handle Errors */}
							{regionCode !== "Region" &&
							!settlement_breakdown &&
							settlement_breakdown_error &&
							settlement_breakdown_error.data && (
								<ErrorMessage message={settlement_breakdown_error.data.message} />
							)}

							{/* Handle Errors */}
							{regionCode !== "Region" &&
							!settlement_breakdown_error &&
							settlement_breakdown &&
							!settlement_breakdown.data && <ErrorMessage message={"No entries for this date!"} />}

							{/* Handle display content */}
							{settlement_breakdown &&
							settlement_breakdown.data && (
								<Table2 hover bordered striped responsive size='sm'>
									<thead>
										<PostingTableHeader
											headerType={"array"}
											headerPayload={SettlemenBreakdownHeader}
										/>
									</thead>
									<tbody>
										<PostingTable
											tableName={"settlement-breakdown"}
											dataRecords={
												settlement_breakdown && settlement_breakdown.data ? (
													settlement_breakdown.data
												) : (
													[]
												)
											}
										/>
									</tbody>
								</Table2>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

export default SettlementBreakdownMain;
